/* ===================== BÀI 14 · Số học, logic, dịch và xoay ===================== */
/* Bài 14 · Số học, logic, dịch và xoay (AMTS-EMB-001-M04-L02, MC51-014) — sinh bởi tools/author/mcu8051/l14.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR14=[{"label":"Ví dụ: ADD và bốn cờ CY, AC, OV, P","code":"; Ví dụ 1: ADD và bốn cờ CY, AC, OV, P\n; Chip: AT89S52, thạch anh 12 MHz.\n        ORG     0000H\n        MOV     A,#7AH                  ; A = 7AH (+122)\n        ADD     A,#46H                  ; A = 7AH + 46H\n        MOV     30H,PSW                 ; chụp PSW sau phép cộng 1\n        ADD     A,#50H                  ; cộng tiếp 50H\n        SJMP    $\n        END\n","note":"Đoán trước: sau ADD A,#46H, A và bốn cờ bằng bao nhiêu? (A = C0H; CY = 0, AC = 1, OV = 1, P = 0; PSW chụp vào ô 30H = 44H.) Sau ADD A,#50H: C0H + 50H = 110H, A = 10H, CY = 1, AC = 0, OV = 0 (−64 + 80 = +16 không tràn có dấu), P = 1.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Cộng 16 bit bằng ADD và ADDC","code":"; Ví dụ 2: cộng hai số 16 bit bằng ADD rồi ADDC\n; X = 31H:30H = 34F0H, Y = 33H:32H = 1235H\n; Z = X + Y ghi vào 41H:40H (byte thấp ở địa chỉ thấp)\n        ORG     0000H\n        MOV     30H,#0F0H               ; X thấp\n        MOV     31H,#34H                ; X cao\n        MOV     32H,#35H                ; Y thấp\n        MOV     33H,#12H                ; Y cao\n        MOV     A,30H\n        ADD     A,32H                   ; byte thấp: không cộng CY cũ\n        MOV     40H,A\n        MOV     A,31H\n        ADDC    A,33H                   ; byte cao: cộng cả nhớ\n        MOV     41H,A\n        SJMP    $\n        END\n","note":"34F0H + 1235H: byte thấp F0H + 35H = 125H → 40H = 25H, CY = 1; byte cao 34H + 12H + 1 = 47H → 41H = 47H. Đổi ADDC thành ADD rồi chạy lại: 41H thành 46H, sai 1 đơn vị ở byte cao (256 ở giá trị 16 bit).","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: SUBB khi quên xóa CY","code":"; Ví dụ 3 (bẫy): SUBB luôn trừ thêm CY\n; Chip: AT89S52, thạch anh 12 MHz.\n        ORG     0000H\n        MOV     A,#0F0H\n        ADD     A,#20H                  ; phép cộng trước để lại CY = 1\n        MOV     A,#50H\n        SUBB    A,#20H                  ; muốn 50H - 20H = 30H\n        MOV     30H,A                   ; ghi kết quả (sai?)\n        CLR     C                       ; xóa CY trước khi trừ\n        MOV     A,#50H\n        SUBB    A,#20H                  ; làm lại đúng cách\n        SJMP    $\n        END\n","note":"Phép cộng F0H + 20H để lại CY = 1. SUBB A,#20H tính 50H − 20H − 1 = 2FH (ô 30H). Sau CLR C, cùng phép trừ cho đúng 30H. 8 chu kỳ tới SJMP $.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: MUL AB và DIV AB","code":"; Ví dụ 4: MUL AB và DIV AB\n; Chip: AT89S52, thạch anh 12 MHz.\n        ORG     0000H\n        MOV     A,#200                  ; A = 200 = C8H\n        MOV     B,#3\n        MUL     AB                      ; B:A = 200 x 3\n        MOV     30H,A                   ; byte thấp của tích\n        MOV     31H,B                   ; byte cao của tích\n        MOV     A,#251                  ; A = 251 = FBH\n        MOV     B,#10\n        DIV     AB                      ; A = thương, B = số dư\n        SJMP    $\n        END\n","note":"MUL AB: 200 × 3 = 600 = 0258H → A = 58H, B = 02H, OV = 1 (tích lớn hơn FFH), 4 chu kỳ. DIV AB: 251 / 10 = 25 dư 1 → A = 19H, B = 01H, OV = 0, CY = 0. Đổi MOV B,#10 thành MOV B,#0 để xem OV = 1 khi chia cho 0.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Mặt nạ ANL, ORL, XRL trên cổng","code":"; Ví dụ 5: mặt nạ ANL, ORL, XRL trên cổng LED\n; Nối dây (giả định): LED sáng khi chân = 0.\n        ORG     0000H\n        ANL     P1,#0F0H                ; xóa 4 bit thấp: LED 0-3 sáng\n        ORL     P1,#03H                 ; đặt bit 0, 1: LED 0, 1 tắt\n        XRL     P1,#81H                 ; đảo bit 0 và bit 7\n        MOV     A,P1                    ; đọc cổng vào A\n        ANL     A,#0FH                  ; giữ 4 bit thấp của A\n        SJMP    $\n        END\n","note":"Xem LED: ANL P1,#0F0H làm LED 0–3 sáng; ORL P1,#03H tắt LED 0, 1 (P1 = F3H); XRL P1,#81H đảo bit 0 và bit 7 (P1 = 72H). MOV A,P1 rồi ANL A,#0FH giữ nửa thấp: A = 02H.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: RL, RLC và SWAP","code":"; Ví dụ 6: RL, RLC và SWAP\n; 31H:30H = 419CH dịch trái 1 bit (nhân 2)\n        ORG     0000H\n        MOV     A,#0FEH                 ; 1111 1110B\n        RL      A                       ; xoay trái: 1111 1101B\n        RL      A                       ; 1111 1011B\n        MOV     P1,A                    ; LED P1.2 sáng\n        MOV     30H,#9CH                ; byte thấp\n        MOV     31H,#41H                ; byte cao\n        CLR     C                       ; bit đưa vào bên phải = 0\n        MOV     A,30H\n        RLC     A                       ; bit 7 cũ sang CY\n        MOV     30H,A\n        MOV     A,31H\n        RLC     A                       ; CY vào bit 0\n        MOV     31H,A\n        SWAP    A                       ; đổi hai nửa 4 bit\n        SJMP    $\n        END\n","note":"RL A hai lần: FEH → FDH → FBH, LED P1.2 sáng. Dịch 419CH sang trái 1 bit: RLC byte thấp 9CH → 38H, CY = 1; RLC byte cao 41H → 83H (nhận CY), kết quả 8338H = 419CH × 2. SWAP A đổi 83H thành 38H.","dev":{"led":true},"fosc":12000000}];
const sim14=makeSim51(document.getElementById("m51-l14"),{id:"s14",presets:PR14,ram:256});
makeEx51(document.getElementById("ex-l14"),"l14",[{"t":"Cộng hai số 16 bit, giữ cả bit nhớ","d":"<p>Số X 16 bit nằm ở <code>31H:30H<\/code>, số Y ở <code>33H:32H<\/code> (byte thấp ở địa chỉ thấp). Tính Z = X + Y gồm 17 bit: byte thấp ghi vào <code>40H<\/code>, byte giữa vào <code>41H<\/code>, bit nhớ ra ngoài 16 bit ghi vào <code>42H<\/code> (<code>00H<\/code> hoặc <code>01H<\/code>). X, Y giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: X = <code>34F0H<\/code>, Y = <code>1235H<\/code> → <code>40H = 25H, 41H = 47H, 42H = 00H<\/code>. X = Y = <code>FFFFH<\/code> → <code>FEH, FFH, 01H<\/code>.<\/p>","start":"; X = 31H:30H, Y = 33H:32H (byte thấp ở địa chỉ thấp)\n; Cần: 42H:41H:40H = X + Y (42H = 00H hoặc 01H)\n        ORG     0000H\n        MOV     A,30H\n        ADD     A,32H                   ; byte thấp\n        MOV     40H,A\n        MOV     A,31H\n        ADD     A,33H                   ; byte cao\n        MOV     41H,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":240,"0x31":52,"0x32":53,"0x33":18,"0x42":238}},"expect":{"iram":{"0x30":240,"0x31":52,"0x32":53,"0x33":18,"0x40":37,"0x41":71,"0x42":0}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x42":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x40":0,"0x41":0,"0x42":0}}},{"setup":{"iram":{"0x30":255,"0x31":255,"0x32":255,"0x33":255,"0x42":238}},"expect":{"iram":{"0x30":255,"0x31":255,"0x32":255,"0x33":255,"0x40":254,"0x41":255,"0x42":1}}},{"setup":{"iram":{"0x30":255,"0x31":0,"0x32":1,"0x33":0,"0x42":238}},"expect":{"iram":{"0x30":255,"0x31":0,"0x32":1,"0x33":0,"0x40":0,"0x41":1,"0x42":0}}},{"setup":{"iram":{"0x30":0,"0x31":128,"0x32":0,"0x33":128,"0x42":238}},"expect":{"iram":{"0x30":0,"0x31":128,"0x32":0,"0x33":128,"0x40":0,"0x41":0,"0x42":1}}},{"setup":{"iram":{"0x30":240,"0x31":240,"0x32":16,"0x33":15,"0x42":238}},"expect":{"iram":{"0x30":240,"0x31":240,"0x32":16,"0x33":15,"0x40":0,"0x41":0,"0x42":1}}}]},"hints":["Chạy code mẫu với bộ thử 4 (00FFH + 0001H): byte cao có nhận được số nhớ từ byte thấp không?","Byte thấp dùng ADD, byte cao phải dùng ADDC để cộng thêm CY của phép cộng trước.","Bit thứ 17 nằm ở CY sau ADDC. Có lệnh nào xóa A mà không đụng CY, và lệnh nào đưa CY vào bit 0 của A?"],"why":"Byte cao phải cộng cả số nhớ của byte thấp (ADDC), và số nhớ sau byte cao là bit thứ 17 của kết quả. Cách lấy CY ra một byte: xóa A (không đụng CY) rồi xoay trái qua CY, A = 00H hoặc 01H. Bộ thử 4 và 6 bắt lỗi dùng ADD cho byte cao, bộ thử 3, 5, 6 bắt lỗi quên byte nhớ."},{"t":"Nhân số 16 bit với số 8 bit","d":"<p>X 16 bit ở <code>31H:30H<\/code> (byte thấp ở 30H), M 8 bit ở <code>32H<\/code>. Tính tích 24 bit X × M: byte thấp vào <code>40H<\/code>, byte giữa vào <code>41H<\/code>, byte cao vào <code>42H<\/code>. Các ô 30H–32H giữ nguyên. Được dùng A, B, R0–R7. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: X = <code>1234H<\/code>, M = <code>10H<\/code> → <code>012340H<\/code>: <code>40H = 40H, 41H = 23H, 42H = 01H<\/code>.<\/p>","start":"; X = 31H:30H (16 bit), M = 32H (8 bit)\n; Cần: 42H:41H:40H = X x M (24 bit)\n        ORG     0000H\n        MOV     A,30H\n        MOV     B,32H\n        MUL     AB                      ; B:A = byte thấp của X x M\n        MOV     40H,A\n        MOV     41H,B\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":52,"0x31":18,"0x32":16,"0x40":238,"0x41":238,"0x42":238}},"expect":{"iram":{"0x30":52,"0x31":18,"0x32":16,"0x40":64,"0x41":35,"0x42":1}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":255,"0x40":238,"0x41":238,"0x42":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":255,"0x40":0,"0x41":0,"0x42":0}}},{"setup":{"iram":{"0x30":255,"0x31":255,"0x32":255,"0x40":238,"0x41":238,"0x42":238}},"expect":{"iram":{"0x30":255,"0x31":255,"0x32":255,"0x40":1,"0x41":255,"0x42":254}}},{"setup":{"iram":{"0x30":255,"0x31":0,"0x32":255,"0x40":238,"0x41":238,"0x42":238}},"expect":{"iram":{"0x30":255,"0x31":0,"0x32":255,"0x40":1,"0x41":254,"0x42":0}}},{"setup":{"iram":{"0x30":1,"0x31":128,"0x32":2,"0x40":238,"0x41":238,"0x42":238}},"expect":{"iram":{"0x30":1,"0x31":128,"0x32":2,"0x40":2,"0x41":0,"0x42":1}}},{"setup":{"iram":{"0x30":0,"0x31":1,"0x32":0,"0x40":238,"0x41":238,"0x42":238}},"expect":{"iram":{"0x30":0,"0x31":1,"0x32":0,"0x40":0,"0x41":0,"0x42":0}}},{"setup":{"iram":{"0x30":255,"0x31":1,"0x32":129,"0x40":238,"0x41":238,"0x42":238}},"expect":{"iram":{"0x30":255,"0x31":1,"0x32":129,"0x40":127,"0x41":1,"0x42":1}}}]},"hints":["Viết X = XH × 256 + XL. Khi đó X × M = XH × M × 256 + XL × M: hai phép MUL AB, mỗi phép cho tích 16 bit trong B:A.","Tích XL × M góp byte 40H và một phần byte 41H; tích XH × M lệch sang trái một byte, góp vào 41H và 42H.","Hai tích chồng lên nhau một byte: byte cao của tích thứ nhất cộng với byte thấp của tích thứ hai. Phải cất byte đó trước khi MUL lần hai ghi đè B."],"why":"Phép nhân nhiều byte làm như nhân tay: hai tích riêng 16 bit cộng lệch nhau một byte. 41H = (byte cao của XL × M) + (byte thấp của XH × M), 42H = byte cao của XH × M + nhớ. Bộ thử 3 (FFFFH × FFH) và 7 kiểm số nhớ khi cộng hai tích riêng."},{"t":"Tách hai chữ số BCD ≤ 9 chu kỳ","d":"<p>Ô <code>30H<\/code> chứa một số BCD nén: 4 bit cao là chữ số hàng chục, 4 bit thấp là chữ số đơn vị (ví dụ <code>47H<\/code> là số 47). Ghi chữ số hàng chục vào <code>40H<\/code>, chữ số đơn vị vào <code>41H<\/code>; <code>30H<\/code> giữ nguyên. Code mẫu dùng <code>DIV AB<\/code> (chia cho 16) nên đúng nhưng tốn 12 chu kỳ máy. Hãy viết lại để toàn chương trình chạy không quá <b>9 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và mã dài không quá <b>15 byte<\/b>.<\/p><p>Ví dụ: <code>30H = 47H<\/code> → <code>40H = 04H, 41H = 07H<\/code>.<\/p>","start":"; 30H chứa số BCD nén (vd 47H). Cần: 40H = chục, 41H = đơn vị.\n; Chạy đúng nhưng chậm: cần <= 9 chu kỳ, <= 15 byte.\n        ORG     0000H\n        MOV     A,30H\n        MOV     B,#16\n        DIV     AB                      ; A = nửa cao, B = nửa thấp\n        MOV     40H,A\n        MOV     41H,B\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":71}},"expect":{"iram":{"0x30":71,"0x40":4,"0x41":7}}},{"setup":{"iram":{"0x30":0}},"expect":{"iram":{"0x30":0,"0x40":0,"0x41":0}}},{"setup":{"iram":{"0x30":153}},"expect":{"iram":{"0x30":153,"0x40":9,"0x41":9}}},{"setup":{"iram":{"0x30":144}},"expect":{"iram":{"0x30":144,"0x40":9,"0x41":0}}},{"setup":{"iram":{"0x30":9}},"expect":{"iram":{"0x30":9,"0x40":0,"0x41":9}}},{"setup":{"iram":{"0x30":88}},"expect":{"iram":{"0x30":88,"0x40":5,"0x41":8}}}],"maxCyc":9,"maxBytes":15},"hints":["DIV AB tốn 4 chu kỳ, MUL/DIV là hai lệnh chậm nhất. Chia cho 16 chỉ là lấy 4 bit cao; lấy dư cho 16 là lấy 4 bit thấp.","ANL A,#0FH giữ 4 bit thấp (1 chu kỳ). SWAP A đổi chỗ hai nửa 4 bit (1 chu kỳ, 1 byte).","Muốn ít byte hơn nữa: một phép XOR giữa số ban đầu và chữ số hàng đơn vị cho lại phần còn lại của byte."],"why":"Chia và lấy dư cho 16 = tách 4 bit cao và 4 bit thấp, làm bằng ANL A,#0FH và SWAP A, mỗi lệnh 1 chu kỳ, thay cho MOV B,#16 + DIV AB (6 chu kỳ). Cách đọc 30H hai lần chạy 9 chu kỳ, 15 byte; cách lấy nửa cao bằng phép XOR giữa chữ số đơn vị và chính ô 30H chỉ 8 chu kỳ, 13 byte."}]);

makeQuiz("quiz14","score14",[{"q": "Sau MOV A,#7AH và ADD A,#46H, giá trị A và các cờ là gì?", "o": ["A = C0H, CY = 1, AC = 1, OV = 0", "A = C0H, CY = 0, AC = 0, OV = 0", "A = 40H, CY = 1, AC = 1, OV = 1", "A = C0H, CY = 0, AC = 1, OV = 1"], "a": 3, "e": "7AH + 46H = C0H (192 < 256 nên CY = 0). Nửa thấp AH + 6H = 10H có nhớ sang bit 4 nên AC = 1. Xét có dấu, +122 + 70 = +192 vượt +127 nên OV = 1."}, {"q": "Vì sao phép trừ 8 bit đầu tiên thường có CLR C đứng trước SUBB?", "o": ["SUBB chỉ chạy được khi CY = 0, nếu không trình dịch báo lỗi", "SUBB luôn trừ thêm CY; CY còn sót từ lệnh trước sẽ làm kết quả nhỏ đi 1", "CLR C xóa A để chuẩn bị phép trừ", "CLR C đặt cờ OV để báo tràn có dấu"], "a": 1, "e": "SUBB A,x tính A − x − CY. 8051 không có lệnh trừ không mượn, nên phải tự xóa CY trước byte đầu tiên. Ví dụ 3: quên CLR C thì 50H − 20H thành 2FH."}, {"q": "Sau MOV A,#200, MOV B,#3, MUL AB, giá trị A, B và OV là gì?", "o": ["A = 02H, B = 58H, OV = 1", "A = 58H, B = 02H, OV = 1", "A = 58H, B = 02H, OV = 0", "A = 0258H, B = 00H, OV = 0"], "a": 1, "e": "200 × 3 = 600 = 0258H. Byte thấp vào A (58H), byte cao vào B (02H). OV = 1 vì tích lớn hơn FFH; CY luôn bị xóa."}, {"q": "P1 đang bằng FFH (8 LED tắt, LED sáng khi chân = 0). Lệnh ANL P1,#0F0H làm gì?", "o": ["P1 = 0FH: LED P1.4–P1.7 sáng", "P1 = F0H nhưng chỉ đổi chân, chốt cổng giữ FFH", "P1 = F0H: LED P1.0–P1.3 sáng, P1.4–P1.7 giữ tắt", "Trình dịch báo lỗi vì ANL chỉ nhận A làm đích"], "a": 2, "e": "ANL với bit 0 trong mặt nạ xóa bit đó, bit 1 giữ nguyên: FFH AND F0H = F0H. ANL trực tiếp,#dữ liệu có thật (mã 53, 3 byte, 2 chu kỳ) và ghi vào chốt cổng."}, {"q": "A = 9CH, CY = 0. Sau RLC A, giá trị A và CY là gì?", "o": ["A = 38H, CY = 1", "A = 39H, CY = 0", "A = 38H, CY = 0", "A = 4EH, CY = 0"], "a": 0, "e": "9CH = 1001 1100B. RLC đẩy bit 7 (1) vào CY và đưa CY cũ (0) vào bit 0: 0011 1000B = 38H, CY = 1. 39H là kết quả của RL A (xoay 8 bit, bit 7 quay về bit 0)."}]);

